function f()
    if x > 0
        a = 1;
      elseif x < 0
        a = -1;
    else
        a = 0;
    end
end
";
        let diags = lint(source);
        assert!(has_id(&diags, "ALIGN"), "got: {diags:?}");
    }

    #[test]
