                        rule_id: "NCOMMA",
                        message: "Use comma to separate input arguments".to_string(),
                        severity: Severity::Info,
                        byte_range: prev.end_byte()..child.start_byte(),
                        line: pos.row + 1,
                        column: pos.column + 1,
                        fix: Some(Fix::new(insert_pos..insert_pos + 1, ", ")),
                    });
                }
            }
            prev_expr = Some(child);
        }
    }
}

